const L = [0];

export function setLanguage(n: number): void {
  if (n >= 0 && n < LANG_COUNT) L[0] = n; else L[0] = 0;
}
export function language(): number { return L[0]; }

/// The string for an id in the current language.
export function T(id: number): string {
  if (L[0] === 1) return T_DE[id];
  if (L[0] === 2) return T_FR[id];
  if (L[0] === 3) return T_ES[id];
  return T_EN[id];
}

/// T(id) with its {0} replaced. Built with indexOf/substring: no split, no regex.
export function fmt(id: number, a: string): string {
  const s = T(id);
  const k = s.indexOf('{0}');
  if (k < 0) return s;
  return s.substring(0, k) + a + s.substring(k + 3);
}
